#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int main() {
    int n, budget;
    std::cin >> n >> budget;
    std::vector<int> array(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> array[i];
    }

    std::vector<int> parityCounter(n);
    parityCounter[0] = (array[0] % 2 == 1) ? 1 : -1;
    for (int i = 1; i < n; ++i) {
        if (array[i] % 2 == 1)
            parityCounter[i] = parityCounter[i - 1] + 1;
        else
            parityCounter[i] = parityCounter[i - 1] - 1;
    }

    std::vector<int> diffArray(n - 1);
    for (int i = 0; i < n - 1; ++i) {
        diffArray[i] = std::abs(array[i + 1] - array[i]);
    }

    std::vector<int> costs;
    for (int i = 1; i < n - 1; ++i) {
        if (parityCounter[i] == 0) {
            costs.push_back(diffArray[i]);
        }
    }

    std::sort(costs.begin(), costs.end());

    int used = 0;
    for (int c : costs) {
        if (budget >= c) {
            budget -= c;
            ++used;
        } else {
            break;
        }
    }

    std::cout << used << std::endl;
    return 0;
}

